import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import {
  LayoutDashboard,
  FileText,
  Settings,
} from 'lucide-react';

const Sidebar = () => {
  const location = useLocation();

  const navItems = [
    {
      name: 'Builder',
      path: '/',
      icon: <LayoutDashboard size={20} />,
    },
    {
      name: 'User Form',
      path: '/form',
      icon: <FileText size={20} />,
    },
    {
      name: 'Settings',
      path: '/settings',
      icon: <Settings size={20} />,
    },
  ];

  return (
    <div className="w-72 bg-white shadow-2xl h-screen p-6 flex flex-col">

      {/* Logo */}
      <div className="mb-10">

        <h1 className="text-3xl font-bold text-blue-600">
          FormFlow
        </h1>

        <p className="text-gray-500 text-sm mt-1">
          Nested Form Builder
        </p>

      </div>

      {/* Navigation */}
      <div className="flex flex-col gap-3">

        {navItems.map((item) => (

          <Link
            key={item.name}
            to={item.path}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-300 ${
              location.pathname === item.path
                ? 'bg-blue-500 text-white shadow-lg'
                : 'hover:bg-gray-100 text-gray-700'
            }`}
          >

            {item.icon}

            <span className="font-medium">
              {item.name}
            </span>

          </Link>

        ))}

      </div>

      {/* Bottom Card */}
      <div className="mt-auto bg-gradient-to-r from-blue-500 to-indigo-500 rounded-2xl p-5 text-white">

        <h2 className="font-bold text-lg mb-2">
          Upgrade UI
        </h2>

        <p className="text-sm opacity-90">
          Create beautiful nested forms with modern UX.
        </p>

      </div>

    </div>
  );
};

export default Sidebar;
